QS=[
Q('מה קובע ס׳ 3 לחוק יסוד: חופש העיסוק?','זכות לעסוק בכל עיסוק, מקצוע או משלח יד',['זכות קניין','חופש הביטוי','חופש הדת'],'ס׳ 3 לחוק יסוד: חופש העיסוק קובע שכל אזרח או תושב זכאי לעסוק בכל עיסוק, מקצוע או משלח יד. חופש הדת וחופש הביטוי נגזרים מכבוד האדם, והקניין מעוגן בחוק יסוד: כבוד האדם וחירותו.'),
Q('על מי חלה הזכות?','אזרחים ותושבים',['כל אדם בעולם','אזרחים בלבד','יהודים בלבד'],'הזכות בחוק יסוד: חופש העיסוק חלה על אזרחים ועל תושבי המדינה, ולא רק על יהודים או רק על אזרחים. הטענה שהיא חלה על כל אדם בעולם רחבה מדי ואינה תואמת את לשון הסעיף.'),
Q('איזה סעיף הוא פסקת ההגבלה בחוק זה?','ס׳ 4',['ס׳ 3','ס׳ 8','ס׳ 10'],'ס׳ 4 הוא פסקת ההגבלה בחוק יסוד: חופש העיסוק: פגיעה מותרת בחוק ההולם את ערכי המדינה, לתכלית ראויה ובמידה שאינה עולה על הנדרש. ס׳ 8 הוא ההתגברות, וס׳ 3 הוא הזכות עצמה.'),
Q('איזה סעיף הוא פסקת ההתגברות?','ס׳ 8',['ס׳ 4','ס׳ 3','ס׳ 1'],'ס׳ 8 הוא פסקת ההתגברות: הוא מאפשר לחוק לעמוד אף שהוא פוגע בחופש העיסוק, אם נקבע בו כך במפורש ברוב חברי הכנסת. ס׳ 4 הוא פסקת ההגבלה, וס׳ 3 הוא הזכות, ולכן אינם ההתגברות.'),
Q('מתי נחקק חוק יסוד: חופש העיסוק מחדש עם התגברות?','1994',['1950','2005','2018'],'חוק היסוד נחקק מחדש ב-1994 עם פסקת התגברות, לאחר חקיקתו הראשונה ב-1992. 2018, 2005 ו-1950 הן שנים שאינן קשורות לחקיקה מחדש של חוק היסוד.'),
Q('האם חופש העיסוק מבטיח רווח?','לא',['כן','כן, תמיד','תלוי בשר'],'חופש העיסוק מבטיח את הזכות לעסוק במקצוע, ולא את הרווח או את ההצלחה הכלכלית. התשובות שכן או שהדבר תלוי בשר מתעלמות מכך שהזכות היא חופש לבחור ולעסוק, ולא ערובה לרווח.'),
Q('מהו ההבדל בין חופש עיסוק לקניין?','קניין הוא זכות נפרדת בחוק כבוד האדם',['אין הבדל','קניין הוא חופש עיסוק','חופש עיסוק הוא קניין'],'הקניין הוא זכות נפרדת המעוגנת בס׳ 3 לחוק יסוד: כבוד האדם וחירותו, ואילו חופש העיסוק מעוגן בחוק יסוד נפרד. הטענה שאחד מהם הוא השני מטשטשת בין שתי זכויות שונות.'),
Q('מהי פגיעה אובייקטיבית בעיסוק?','מכסות או מספר מוגבל של רישיונות',['דרישת השכלה','בדיקת רישיון נהיגה','תנאי בטיחות'],'מכסות או הגבלת מספר הרישיונות הן פגיעה אובייקטיבית בחופש העיסוק: יכולתו של אדם לעסוק אינה תלויה בכישוריו אלא במספר המקומות. דרישת השכלה, רישיון נהיגה ובטיחות הן תנאים אישיים או הסדרה.'),
Q('איזו פגיעה בדרך כלל חמורה פחות?','הסדרת אופן העיסוק',['איסור על עיסוק','מכסות','איסור יבוא'],'הסדרת אופן העיסוק, כמו שעות פעילות או תנאי בטיחות, פוגעת פחות מאיסור על עיסוק, איסור יבוא או מכסות, שחוסמים את הכניסה למקצוע או מגבילים אותה. לכן בחינת המידתיות מחמירה יותר באיסורים.'),
Q('מהי תכלית ראויה אופיינית?','הגנה על בריאות הציבור',['מניעת תחרות','הגנה על ותיקים בלבד','פגיעה בקבוצה'],'הגנה על בריאות הציבור היא תכלית ראויה אופיינית להסדרת מקצוע. מניעת תחרות, פגיעה בקבוצה והגנה על ותיקים בלבד הן תכליות פסולות או חשודות, כי הן מפלות או משרתות אינטרס צר.'),
Q('מה בדקה פרשת לשכת מנהלי ההשקעות?','יישום פסקת ההגבלה בהסדרת מקצוע',['התגברות','פסילת מפלגה','שוויון'],'פרשת לשכת מנהלי ההשקעות עסקה ביישום פסקת ההגבלה על הסדרת מקצוע, כלומר בבחינת התכלית והמידתיות של דרישות הרישוי. פסילת מפלגה, התגברות ושוויון אינם נושא הפרשה.'),
Q('מה נקבע במיטראל?','פגיעה בחופש העיסוק דורשת בסיס חקיקתי מפורש',['אין הגנה על העיסוק','הרשות חופשית','אסור לייבא בשר'],'במיטראל נקבע שפגיעה בחופש העיסוק דורשת בסיס חקיקתי מפורש, ולכן הגבלת יבוא בשר שנעשתה מנהלית בלי הסמכה מפורשת לא עמדה. הטענה שאין הגנה על העיסוק או שהרשות חופשית סותרת את ההלכה.'),
Q('מה הייתה תגובת הכנסת לפסיקת מיטראל?','הוספת פסקת התגברות וחקיקת חוק יבוא בשר',['ביטול בג"ץ','חקיקת חוק יסוד חדש','שינוי חוק השבות'],'בתגובה לפסיקת מיטראל חוקקה הכנסת את חוק יבוא בשר והוסיפה לחוק יסוד: חופש העיסוק פסקת התגברות. שינוי חוק השבות, ביטול בג"ץ או חוק יסוד חדש אינם התגובה שנקבעה.'),
Q('מהם תנאי ההתגברות?','אמירה מפורשת, רוב חברי הכנסת, ארבע שנים',['רוב הנוכחים','אישור בג"ץ','פה אחד'],'ס׳ 8 מתנה התגברות בכך שהחוק יאמר במפורש שהוא תקף אף שהוא סותר את חוק היסוד, שיתקבל ברוב חברי הכנסת, ושתוקפו יוגבל לארבע שנים. פה אחד, אישור בג"ץ או רוב הנוכחים אינם התנאים.'),
Q('איזו זכות היא היחידה עם פסקת התגברות?','חופש העיסוק',['כבוד האדם','שוויון','ביטוי'],'חוק יסוד: חופש העיסוק הוא היחיד מבין חוקי היסוד בזכויות שכולל פסקת התגברות, ולכן חופש העיסוק הוא התשובה. כבוד האדם, שוויון וביטוי אינם בעלי פסקה כזו.'),
Q('למה חשובים הסדרי מעבר?','כדי להגן על עוסקים ותיקים בהסדרת מקצוע',['כדי להגדיל רווחים','כדי למנוע רישוי','כדי לפטור כולם'],'הסדרי מעבר נועדו להגן על עוסקים ותיקים בהסדרת מקצוע, כדי שהפגיעה בהם תהיה מידתית. הגדלת רווחים, פטור כולם או מניעת רישוי אינם תכליתם.'),
Q('מהי דרישת רישוי?','תנאי כניסה אישי למקצוע',['איסור מוחלט','מכסה','מס'],'דרישת רישוי היא תנאי כניסה אישי למקצוע, כמו הכשרה והסמכה. מכסה היא מגבלה אובייקטיבית, מס הוא חיוב כספי, ואיסור מוחלט שולל את העיסוק כליל.'),
Q('מה בדיקת הפגיעה בעיסוק?','האם החוק פוגע בבחירה, בכניסה או בעיסוק',['האם החוק ישן','האם החוק קצר','האם החוק יקר'],'בחינת הפגיעה בעיסוק בודקת אם החוק פוגע בחופש לבחור מקצוע, להיכנס אליו או לעסוק בו. העובדה שהחוק ישן, קצר או יקר אינה קריטריון לפגיעה בחופש העיסוק.'),
Q('מה נבחן אחרי שהוכחה פגיעה?','פסקת ההגבלה',['שיהוי','בשלות','עמידה'],'לאחר שהוכחה פגיעה בחופש העיסוק, נבחנת פסקת ההגבלה: חוק ההולם את ערכי המדינה, תכלית ראויה ומידתיות. עמידה, שיהוי ובשלות הם תנאי סף להגשת עתירה ולא שלב בבחינת הפגיעה.'),
Q('חוק יבוא בשר נחקק:','בפסקת התגברות',['בחוק יסוד','בתקנות','בפסיקה'],'חוק יבוא בשר נחקק עם פסקת התגברות, כלומר הוא תקף אף שהוא פוגע בחופש העיסוק. הוא לא נקבע בפסיקה, בתקנות או בחוק יסוד, ולכן האפשרויות האחרות שגויות.'),
Q('איזה אמצעי עשוי להיות פחות פוגע בוותיקים?','הסדר מעבר',['איסור מיידי','מכסה','קנס'],'הסדר מעבר מאפשר לוותיקים להמשיך לעסוק בתנאים מותאמים בעת שינוי הרישוי, ולכן פוגע בהם פחות מאיסור מיידי. קנס, איסור מיידי ומכסה מחמירים את הפגיעה בעוסקים קיימים.'),
]
